/****** Objeto: View [dbo].[vw_ReporteMantenimientoPresupuestoLooker] Fecha de script: 12/11/2026 11:17:07 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   VIEW [dbo].[vw_ReporteMantenimientoPresupuestoLooker] AS
WITH ResumenMantenimiento AS (
    SELECT 
        m.IdEstacion,
        YEAR(m.FechaProgramada) AS Anio,
        SUM(CASE WHEN m.Estado = 'Ejecutado' THEN m.CostoUSD ELSE 0.00 END) AS CostoTotalEjecutadoUSD,
        SUM(CASE WHEN m.Estado = 'Ejecutado' AND m.TipoMantenimiento = 'Preventivo' THEN m.CostoUSD ELSE 0.00 END) AS CostoPreventivoUSD,
        SUM(CASE WHEN m.Estado = 'Ejecutado' AND m.TipoMantenimiento = 'Correctivo' THEN m.CostoUSD ELSE 0.00 END) AS CostoCorrectivoUSD,
        COUNT(CASE WHEN m.TipoMantenimiento = 'Preventivo' AND m.Estado IN ('Demorado', 'Cancelado') AND m.EsFechaCritica = 1 THEN 1 END) AS PreventivosCriticosFallidos,
        COUNT(CASE WHEN m.TipoMantenimiento = 'Correctivo' AND m.Estado = 'Ejecutado' THEN 1 END) AS CorrectivosEjecutados
    FROM dbo.Mantenimiento m
    GROUP BY m.IdEstacion, YEAR(m.FechaProgramada)
)
SELECT 
    p.Anio,
    CAST(CONCAT(p.Anio, '-01-01') AS DATE) AS FechaAnio,
    e.IdEstacion,
    e.NombreEstacion,
    e.Provincia,
    e.PerfilDemanda,
    p.PresupuestoMantenimientoUSD,
    ISNULL(rm.CostoTotalEjecutadoUSD, 0.00) AS GastoRealUSD,
    ISNULL(rm.CostoPreventivoUSD, 0.00) AS GastoPreventivoUSD,
    ISNULL(rm.CostoCorrectivoUSD, 0.00) AS GastoCorrectivoUSD,
    ISNULL(rm.CostoTotalEjecutadoUSD, 0.00) - p.PresupuestoMantenimientoUSD AS DesvioUSD,
    CASE 
        WHEN p.PresupuestoMantenimientoUSD > 0 
        THEN ROUND(((ISNULL(rm.CostoTotalEjecutadoUSD, 0.00) - p.PresupuestoMantenimientoUSD) / p.PresupuestoMantenimientoUSD) * 100.0, 2)
        ELSE 0.00 
    END AS DesvioPct,
    ISNULL(rm.PreventivosCriticosFallidos, 0) AS PreventivosCriticosFallidos,
    ISNULL(rm.CorrectivosEjecutados, 0) AS CorrectivosEjecutados
FROM dbo.PresupuestosAnualesEstacion p
JOIN dbo.Estaciones e 
    ON p.IdEstacion = e.IdEstacion
LEFT JOIN ResumenMantenimiento rm 
    ON p.IdEstacion = rm.IdEstacion 
   AND p.Anio = rm.Anio
WHERE p.Anio >= 2023;

GO
